import { createApiCall, HttpMethod } from "./api";
import { AdvancedSearchEndPoints } from "@/constants/ApiConstants";
import { AdvancedSearchPayload } from "@/types/advancedSearch.types";

export const AdvancedSearchServicesError = {
    AdvancedSearchError: (status: number): string => {
        switch (status) {
            case 0: return 'No internet connection. Please check your network and try again.';
            case 400: return 'Some filters are invalid. Please review them and try again.';
            case 401: return 'Your session has expired. Please login again to search.';
            case 403: return 'Access denied. You do not have permission to search.';
            case 429: return 'You are searching too frequently. Please wait a moment.';
            case 500: return 'Something went wrong on our end. Please try again later.';
            default: return 'Advanced search failed. Please try again.';
        }
    },
};

export const AdvancedSearchServices = {
    // Authenticated: multi-filter search across profiles and businesses. All filters are ANDed.
    Search: async (payload: AdvancedSearchPayload) =>
        createApiCall(HttpMethod.POST, AdvancedSearchEndPoints.Search(), payload),
};
